/**
 * utils/mutate.js: issue a Supabase write and hand back an error that is already a message.
 *
 * Every write must check its `{ error }` and route it through `humanizeError` before any success
 * UI appears. Ignoring the error is one keystroke SHORTER than obeying it, which is why this
 * exists: obeying the rule is now the shorter path. This is the MECHANISM only; which surface
 * the message reaches stays at the call site as a per-screen decision.
 *
 * @invariant the returned `error` is null or a `humanizeError` feedback object, never a raw
 *            Supabase error. Nothing downstream may humanize it again: passing the object back
 *            in returns `{ tone: 'error', title: <object> }` and React renders nothing.
 * @gotcha a write that never reaches the server REJECTS rather than resolving `{ error }`, so
 *         the catch is not belt and braces. Without it an offline click is the same silent
 *         nothing this removes, and it skips whatever `setSaving(false)` sits after the await.
 * @see utils/errors.js `humanizeError`
 */
import { humanizeError } from './errors';

/**
 * Await a Supabase write and normalise its outcome.
 *
 * @param {PromiseLike<{data: *, error: *}>} builder - a PostgREST query builder,
 *        or anything else resolving to a `{ data, error }` pair.
 * @returns {Promise<{data: *, error: ?{tone: string, title: string, body: ?string}}>}
 *          `error` is null on success, so `if (error)` is the whole check. It
 *          never rejects: a thrown request comes back through `error` too.
 */
export async function mutate(builder) {
  try {
    const { data, error } = await builder;
    return { data: data ?? null, error: humanizeError(error) };
  } catch (e) {
    return { data: null, error: humanizeError(e) };
  }
}
