/**
 * utils/invoiceMath.js - receipt-side math for invoices, and the campaign invoice
 * row the Payments editor writes.
 *
 * The user enters Net Received + Discount; Processing Fee is DERIVED (the
 * remainder), never typed. All inputs accept numbers or empty strings ('' from
 * form inputs); null/undefined are treated as empty.
 *
 * @invariant invoice_amount = amount_received + processing_fee + discount_amount.
 *            This mirrors create_invoice_received_entry's balance assertion
 *            (v_received + v_fee + v_discount must equal the invoice amount), so
 *            UI-side and DB-side math can never post a JE that fails to balance.
 * @see docs/MONEY.md (invoice receipt patterns B/D)
 */
import { round2 } from './format';

/** Coerce a form value to a finite number, or null for empty/invalid input. */
function toNumOrNull(v) {
  if (v === '' || v === null || v === undefined) return null;
  const n = typeof v === 'number' ? v : parseFloat(v);
  return Number.isFinite(n) ? n : null;
}

/**
 * Derived processing fee = invoice - net - discount, cents-rounded.
 *
 * @returns {number} 0 when invoiceAmount or netReceived is missing.
 * @gotcha Clamped to >= 0 so a malformed over-discount renders 0 rather than a
 *         negative fee; validateReceiptSums is what actually blocks the save.
 */
export function computeProcessingFee(invoiceAmount, netReceived, discountAmount) {
  const inv = toNumOrNull(invoiceAmount);
  const net = toNumOrNull(netReceived);
  if (inv == null || net == null) return 0;
  const disc = toNumOrNull(discountAmount) ?? 0;
  return Math.max(0, Math.round((inv - net - disc) * 100) / 100);
}

/**
 * Total actually banked across a set of receipt-bearing rows.
 *
 * Takes `campaign_payout_summary` / `reward_payout_summary` shaped rows and totals
 * only those flagged `you_received`. Owns the whole "how much came in" expression,
 * filter included, so a caller cannot apply half of it.
 *
 * @param {Array<object>} rows receipt rows; anything not an array totals 0.
 * @returns {number} unrounded sum.
 * @gotcha `amount_received` is ALREADY NET of the fee (see the file @invariant), so
 *         subtracting `processing_fee` here would deduct it twice. RewardsPage did
 *         exactly that and understated its "You Received" tile by the entire fee
 *         total, $268.92 over 25 live rows, while the identically labelled Payments
 *         tile read the truth. That divergence is why this helper exists.
 * @gotcha the fallback is `??`, NOT the `||` all four original call sites wrote. A
 *         genuinely zero receipt must total 0, and `0 || x` is `x`, which reported
 *         the full contracted figure as banked. Only a missing value may fall
 *         through.
 */
export function receivedTotal(rows) {
  if (!Array.isArray(rows)) return 0;
  return rows.reduce(
    (sum, r) => (r && r.you_received ? sum + (r.amount_received ?? r.invoice_amount ?? 0) : sum),
    0,
  );
}

/**
 * Is this invoice settled, so nothing may offer a payment link for it?
 *
 * Mirrors the `canPayNow` gate in `supabase/functions/agency-dashboard/index.ts`, which is the
 * authority: that gate withholds the Stripe URL from the agency entirely, so any client surface
 * that disagrees offers a checkout for money the agency cannot pay and we may already hold.
 *
 * @param {object} invoice a row carrying `is_in_kind`.
 * @param {string} [statusValue] the RESOLVED `status_options.value` for the row's
 *        `payment_status_id`, not the id itself.
 * @returns {boolean}
 * @gotcha the two tests are not interchangeable and both are needed. `is_in_kind` is a column
 *         on the invoice; `'Paid'` is a status row's value. Production carries an invoice that
 *         is in kind while its status reads Pending, so a client testing only the status would
 *         hand a creator a live checkout for it.
 * @gotcha the status value `'In Kind'` is deliberately NOT a third test. The column is the
 *         authority, the server tests only the column, and adding it would re-open the gap
 *         between the two tiers from the other side.
 */
export function isSettledInvoice(invoice, statusValue) {
  if (!invoice) return false;
  return invoice.is_in_kind === true || statusValue === 'Paid';
}

/**
 * Have the goods on an in-kind deal physically arrived?
 *
 * THE ONE HOME for what `you_received` means on an in-kind row, because it means something
 * different there than it does on a cash one and nothing else in the schema says so.
 *
 * On a cash invoice `you_received` is "the money cleared my account" and posts Pattern B. On
 * an in-kind invoice it is "the box turned up", posts nothing, and is the only record that
 * the deal completed. The pair was chosen over a new column because the names already read
 * correctly and every existing consumer is guarded: `TaxEstimate`, `PayrollTab`,
 * `MyMoneyPage` and five `ledger_health_check` invariants all test `is_in_kind` before they
 * read `you_received`, so flipping it on an in-kind row moves no money figure anywhere.
 *
 * @param {object} invoice a row carrying `is_in_kind` and `you_received`.
 * @returns {boolean} false for a cash invoice, whatever its receipt state.
 * @gotcha guarded on `is_in_kind` deliberately, and NOT a bare `you_received` read. A cash
 *         invoice that has cleared also carries the flag, and a caller that forgot the guard
 *         would report every paid campaign as a delivered parcel.
 * @gotcha `create_invoice_received_entry` returns early on `is_in_kind` ("in-kind has no cash
 *         receipt"), so no "Cash received%" entry ever exists for one of these rows. That is
 *         also why `prevent_invoice_trigger_field_mutation` never seals the field here: the
 *         arrival date stays correctable forever, which is the behaviour we want.
 */
export function inKindGoodsArrived(invoice) {
  return invoice?.is_in_kind === true && invoice?.you_received === true;
}

/**
 * The payment status a deal should carry after crossing between cash and product.
 *
 * The two vocabularies do not overlap: 'In Kind' is meaningless on a cash invoice, and
 * 'Paid' and 'Overdue' are meaningless on a deal where no cash was ever due. A cross that
 * left the old value behind put a deal on the Payments screen under a status describing
 * money that does not exist.
 *
 * Only the statuses that cannot survive the cross are remapped. 'Not Invoiced' or 'Pending'
 * going in-kind becomes 'In Kind'; everything else the caller already holds is left alone,
 * because a status that still reads correctly is not this function's business.
 *
 * @param {object[]} paymentOptions the `payment` group from status_options
 * @param {string} currentStatusId the id the row carries now
 * @param {boolean} nowInKind the type the row is crossing TO
 * @returns {string} the id to write, which is `currentStatusId` when no remap is needed
 * @gotcha the STORED value stays 'In Kind' whatever an agency-facing dropdown chooses to
 *         show; the agency lists filter that option out, they do not rename it.
 */
export function crossedKindStatusId(paymentOptions, currentStatusId, nowInKind) {
  const opts = paymentOptions || [];
  const current = opts.find(o => o.id === currentStatusId);
  // A row with no status at all still needs one on the way in-kind, so the absent case is
  // handled before the read of `current.value` rather than returned early.
  if (nowInKind) return current?.value === 'In Kind' ? currentStatusId : (opts.find(o => o.value === 'In Kind')?.id || currentStatusId);
  if (current?.value === 'In Kind') return opts.find(o => o.value === 'Pending')?.id || currentStatusId;
  return currentStatusId;
}

/**
 * Build the `invoices` row a campaign invoice save writes, from the editor's form state.
 *
 * Cash and in-kind are one row shape with different fields populated, which is why this is one
 * function with a branch: a caller picking the wrong one would write a half-populated row.
 *
 * @param {object} form the editor's form state. Strings come off inputs, so '' means empty and
 *        is normalised to null here.
 * @returns {object} the `invoices` payload, ready for insert or update.
 *
 * @gotcha THE FEE IS COMPUTED OFF THE CASH FIELD, NOT THE RETURNED AMOUNT. On an in-kind row
 *         `invoice_amount` is the fair market value while the fee is fed `form.invoice_amount`.
 *         Passing the returned amount in looks like a tidy-up and breaks the file invariant
 *         `invoice_amount = amount_received + processing_fee + discount_amount`.
 * @gotcha BOTH stored money fields are rounded ONCE and the same rounded values feed the fee,
 *         which is what makes that invariant hold by construction. `invoice_amount` is
 *         deliberately NOT rounded: it is the contracted figure printed on the issued PDF, and
 *         sub-cent input is refused at the control instead.
 * @see docs/MONEY.md
 */
export function buildCampaignInvoicePayload(form) {
  const inKind = form.is_in_kind;
  const discountVal = inKind ? 0 : (form.discount_amount !== '' ? round2(form.discount_amount) : 0);
  const netVal = inKind ? null : (form.net_received !== '' ? round2(form.net_received) : null);
  return {
    po_number:             form.po_number.trim() || null,
    invoice_date:          form.invoice_date || null,
    due_date:              form.due_date || null,
    invoice_amount:        inKind
                             ? (form.in_kind_value !== '' ? parseFloat(form.in_kind_value) : null)
                             : (form.invoice_amount !== '' ? parseFloat(form.invoice_amount) : null),
    currency:              form.currency || 'USD',
    payment_status_id:     form.payment_status_id || null,
    payment_received_date: form.payment_received_date || null,
    payment_method:        form.payment_method || null,
    payment_notes:         form.payment_notes || null,
    is_in_kind:            form.is_in_kind,
    in_kind_value:         inKind && form.in_kind_value !== '' ? parseFloat(form.in_kind_value) : null,
    in_kind_description:   inKind ? (form.in_kind_description || null) : null,
    // NOT branched on `inKind`, deliberately. On an in-kind row this pair means THE GOODS
    // ARRIVED (@see inKindGoodsArrived), so pinning it to false here would erase the arrival
    // on the next save of any other field on the record.
    // `chk_invoices_received_needs_date` covers both kinds: an arrival has a date too.
    you_received:          form.you_received,
    you_received_date:     form.you_received_date || null,
    // Receipt NOTES stay cash-only. There is no processor, no short collection and no
    // reconciliation to narrate on a parcel; what was in it is `in_kind_description`.
    you_received_notes:    inKind ? null : (form.you_received_notes || null),
    amount_received:       netVal,
    discount_amount:       discountVal,
    processing_fee:        inKind ? 0 : computeProcessingFee(form.invoice_amount, netVal, discountVal),
    service_description:   form.service_description.trim() || null,
    invoice_notes:         form.invoice_notes.trim() || null,
  };
}

/**
 * True when a value TYPED INTO A CONTROL carries more precision than a cent.
 *
 * @gotcha strings only, and that is the whole design rather than an oversight. It is a question
 *         about what the user typed, and only the string still holds that: 100.005 is not
 *         exactly representable as a double, so by the time a value is a number the difference
 *         between "typed 100.005" and "computed 100.00499999999999" is gone, and refusing on the
 *         decimal expansion of a float would reject an arithmetic result for the sin of being a
 *         float. Both live callers pass either a form string (`PaymentsPage`) or a
 *         `numeric(10,2)` column value (`RewardsPage`'s `gross_amount`), which cannot be
 *         sub-cent. It is also what keeps the epsilon in the comparisons below meaningful: the
 *         `tolerates sub-cent rounding noise` case passes numbers and is about that epsilon.
 */
function hasSubCentPrecision(value) {
  if (typeof value !== 'string' || value === '') return false;
  const m = /^\s*-?\d*\.(\d+)\s*$/.exec(value);
  return !!m && m[1].length > 2;
}

/**
 * Pre-save guard for the receipt sums.
 *
 * @security The sub-cent test is the security half
 *           and it is a denial of the accounting path rather than a way to gain anything.
 *           `invoice_amount` is deliberately not rounded (see `buildCampaignInvoicePayload`),
 *           `invoices.invoice_amount` is `numeric(10,2)` so Postgres rounds it on store, and
 *           `processing_fee` was derived from the UNROUNDED value. `create_invoice_received_entry`
 *           then compares its debit and credit totals on exact inequality with no tolerance, so
 *           a three-decimal amount saves fine and the cash receipt for it can never be posted:
 *           money received in the world, unrecordable in the books, from a screen offering no
 *           clue that a third decimal is the reason. Refusing the input is what the payload
 *           builder's own header argues for, and rounding harder is not, because the contracted
 *           figure is already printed on the issued PDF.
 * @returns {string|null} a user-facing error string when a value carries sub-cent precision, or
 *          when net (or net+discount) exceeds the invoice amount, else null. The second case
 *          blocks the one that would force a negative processing fee and trip the JE balance
 *          assertion at post time.
 */
export function validateReceiptSums(invoiceAmount, netReceived, discountAmount) {
  for (const [label, value] of [
    ['Invoice amount', invoiceAmount],
    ['Net received', netReceived],
    ['Discount', discountAmount],
  ]) {
    if (hasSubCentPrecision(value)) {
      return `${label} ($${value}) is more precise than a cent. Enter whole cents.`;
    }
  }
  const inv = toNumOrNull(invoiceAmount);
  const net = toNumOrNull(netReceived);
  if (inv == null || net == null) return null;
  const disc = toNumOrNull(discountAmount) ?? 0;
  if (net > inv + 0.005) {
    return `Net received ($${net.toFixed(2)}) cannot exceed invoice amount ($${inv.toFixed(2)}).`;
  }
  if (net + disc > inv + 0.005) {
    return `Net received + discount ($${(net + disc).toFixed(2)}) cannot exceed invoice amount ($${inv.toFixed(2)}).`;
  }
  return null;
}

/**
 * What was taken out of an invoice before the money reached us.
 *
 * The processing fee AND the discount, because both are the same thing from the creator's
 * side: an amount that was billed and never banked. What two answers to this cost: My Payments
 * summed the fee alone and My Money summed both, both cards said "Fees", and for any invoice
 * carrying a write-off the two screens disagreed by exactly that write-off with nothing on
 * either one to explain the gap.
 *
 * @param {object|null} invoice a row carrying `processing_fee` and `discount_amount`
 * @returns {number} the two, summed and rounded to cents; 0 for a row carrying neither
 *
 * @invariant this is a TERM in My Money's identity (total = landed + held + onway + gear +
 *            recharge + waiting + fees + inKind). Narrowing it does not remove money from the
 *            screen, it pushes that money into the residual, which that screen's own header
 *            forbids being relabeled.
 * @gotcha PostgREST returns `numeric` as a STRING, so both halves go through Number before
 *         they are added. `'12.50' + '100.00'` is a 260-character-wide bug.
 */
export function invoiceFees(invoice) {
  return round2((Number(invoice?.processing_fee) || 0) + (Number(invoice?.discount_amount) || 0));
}
