/**
 * components/shared/OutstandingList.js: what is still standing between the reader and the
 * button they just found greyed out.
 *
 * A `disabled` built from five conditions is a control that refuses without saying why, and
 * the reader's only move is to guess which of the five it is. This is the visible half of the
 * fix; the other half is at the call site and matters more: the gate is derived from the
 * LENGTH of this list, so a condition that greys the button is a condition that names itself
 * and the two cannot drift apart.
 *
 * Lifted verbatim from `components/creator/MobilePostPage.js`, which solved this first for
 * `outstandingPostRequirements` and is still its largest caller. Nothing here is new: it is
 * the same box, the same heading and the same list, in one place so the fourth site is not a
 * fourth copy of the markup.
 *
 * @gotcha it renders NOTHING when the list is empty, so a call site can mount it
 *         unconditionally. A box saying "nothing outstanding" over an enabled button is a
 *         sentence the reader does not need to read.
 * @gotcha a TRANSIENT flag is not a requirement and must not be in the list: `saving`,
 *         `loading`, `submitting`. The button's own label already says those, and a list item
 *         that appears for 300ms and cannot be acted on is noise. Leave them on `disabled`
 *         beside `items.length > 0`.
 * @see utils/markPosted.js outstandingPostRequirements
 */
import React from 'react';

/**
 * @param {Array<{key: string, label: string}>} props.items in the order the controls appear
 *        on screen, so the first outstanding item is also the highest one to scroll back to
 * @param {string} [props.heading='Before you can save'] what the reader is being stopped from
 * @param {object} [props.style] per-site spacing only; never colour or type
 */
export default function OutstandingList({ items, heading = 'Before you can save', style }) {
  if (!items || !items.length) return null;
  return (
    <div className="outstanding-list" style={style}>
      <div className="outstanding-list-heading">{heading}</div>
      <ul className="outstanding-list-items">
        {items.map(r => <li key={r.key}>{r.label}</li>)}
      </ul>
    </div>
  );
}
