/**
 * utils/statusValues.js: the one home for `status_options` row VALUES the hub compares as
 * string literals.
 *
 * Those rows are created by no file in this repository and are edited in Admin > Config >
 * Workflow Setup, so nothing at build time can tell a live value from a typo. A literal that
 * matches no row is a filter that silently returns nothing, which renders as a real zero.
 *
 * @invariant every literal here resolves to a live `status_options` row. Checked two ways,
 *            because neither alone is enough: `utils/__tests__/statusVocabulary.test.js` fails
 *            if a hub file compares a status literal not listed here, and the
 *            `status-vocabulary` System Health check reads the table and reports any literal
 *            here that no row carries.
 * @gotcha Adding a value here does NOT create the row. If Workflow Setup has no such row the
 *         health check goes degraded, which is the point.
 * @see utils/systemHealthChecks.js
 */

/**
 * Payment statuses that mean an invoice has been raised, so an issued PDF should
 * exist for it. Mirrored in SQL by `v_billed_set` in `create_invoice_ar_entry`
 * and `trg_fn_invoice_update_ledger` (`schemas/SCHEMA.sql`), which cannot import
 * this file; `utils/__tests__/schemaMirrors.test.js` holds the two together.
 */
export const BILLED_PAYMENT_VALUES = ['Invoiced', 'Pending', 'Overdue', 'Paid'];

/** Payment status meaning the money arrived. */
export const PAID_PAYMENT_VALUE = 'Paid';

/** Payment status for a deal settled in product rather than cash. */
export const IN_KIND_PAYMENT_VALUE = 'In Kind';

/**
 * Payout status meaning the creator has the money.
 *
 * Spelled the same as PAID_PAYMENT_VALUE and deliberately not shared with it: the two are
 * compared against different columns, and a group is what makes a status value mean anything.
 * @see utils/statusRow.js (the same reason resolution takes a group)
 */
export const PAID_PAYOUT_VALUE = 'Paid';

/**
 * What a payout with NO status at all means.
 *
 * `creator_payouts.payout_status_id` is nullable and carries an FK with ON DELETE RESTRICT, so
 * an orphan id is impossible and the absence is the only unmatched case. It is a real state:
 * a payout row exists and nobody has moved it yet, which is Pending. Named HERE because the
 * badge and the filter beside it each spelled the same default as a literal, and two spellings
 * of one default are two defaults. @see components/shared/StatusBadges.js
 */
export const PAYOUT_DEFAULT_VALUE = 'Pending';

/** The campaign lifecycle, in `sort_order`. */
export const CAMPAIGN_ACTIVE    = 'Active';
export const CAMPAIGN_COMPLETED = 'Completed';
export const CAMPAIGN_CANCELLED = 'Cancelled';

/** The deliverable lifecycle, in `sort_order`. */
export const DELIVERABLE_NOT_STARTED = 'Not Started';
export const DELIVERABLE_APPROVED    = 'Approved';
export const DELIVERABLE_POSTED      = 'Posted';

/**
 * Every literal above, grouped the way `status_options.group_key` groups them.
 * Read by the vocabulary test and by the System Health check; not for feature
 * code, which should import the named constant it actually means.
 */
export const STATUS_VOCABULARY = {
  campaign: [CAMPAIGN_ACTIVE, CAMPAIGN_COMPLETED, CAMPAIGN_CANCELLED],
  deliverable: [
    DELIVERABLE_NOT_STARTED, 'Draft Submitted', 'Revisions Requested',
    DELIVERABLE_APPROVED, 'Scheduled', DELIVERABLE_POSTED,
  ],
  // Listed in sort_order, which is not the order BILLED_PAYMENT_VALUES uses.
  payment: ['Not Invoiced', 'Invoiced', 'Pending', 'Paid', 'Overdue', IN_KIND_PAYMENT_VALUE],
  payout: [PAYOUT_DEFAULT_VALUE, PAID_PAYOUT_VALUE, 'N/A'],
  split: ['Pending', 'Cleared'],
};
