/**
 * utils/expenses.js - recurring-expense occurrence generation + coverage math.
 *
 * Expands a recurring expense (weekly/monthly/quarterly/annual) into the
 * concrete dates that fall in a range, and reports how fully each occurrence has
 * been paid for. Recurring amounts are price-history aware (getEffectiveAmount);
 * never read expenses.amount directly for a recurring expense.
 *
 * @gotcha All date math uses parseLocalDate (local-midnight), never
 *         new Date('YYYY-MM-DD') (UTC-midnight = previous day in US zones).
 * @see docs/MONEY.md (expenses), expense_price_history table
 */

/** Parse a 'YYYY-MM-DD' string as LOCAL midnight (avoids the UTC off-by-one). */
export function parseLocalDate(str) {
  if (!str) return null;
  const [y, m, d] = str.split('-').map(Number);
  return new Date(y, m - 1, d);
}

/** Normalise an expense's amount to a per-month figure for its frequency. */
export function toMonthlyAmount(expense) {
  const amt = parseFloat(expense.amount);
  switch (expense.frequency) {
    case 'weekly':    return (amt * 52) / 12;
    case 'monthly':   return amt;
    case 'quarterly': return amt / 3;
    case 'annual':    return amt / 12;
    default:          return 0;
  }
}

/**
 * Advance one period from `from`, respecting the recurrence config.
 * @gotcha recurrence_day_of_month === 0 means "last day of month"; other days
 *         are clamped to the month length so Jan 31 -> Feb 28/29.
 */
export function nextOccurrence(from, expense) {
  const { frequency, recurrence_day_of_month, start_date } = expense;
  const start = parseLocalDate(start_date);
  const dom = recurrence_day_of_month != null
    ? parseInt(recurrence_day_of_month)
    : (start ? start.getDate() : 1);

  switch (frequency) {
    case 'weekly':
      return new Date(from.getFullYear(), from.getMonth(), from.getDate() + 7);

    case 'monthly': {
      const y = from.getFullYear(), m = from.getMonth() + 1;
      if (dom === 0) return new Date(y, m + 1, 0); // last day
      const cap = new Date(y, m + 1, 0).getDate();
      return new Date(y, m, Math.min(dom, cap));
    }

    case 'quarterly': {
      const next = new Date(from.getFullYear(), from.getMonth() + 3, 1);
      const y = next.getFullYear(), m = next.getMonth();
      if (dom === 0) return new Date(y, m + 1, 0);
      const cap = new Date(y, m + 1, 0).getDate();
      return new Date(y, m, Math.min(dom, cap));
    }

    case 'annual':
      return new Date(from.getFullYear() + 1, from.getMonth(), from.getDate());

    default:
      return null;
  }
}

/**
 * All occurrences of an expense within [rangeStart, rangeEnd].
 *
 * @returns {Array<{date: Date, periodKey: string|null, isFuture: boolean}>}
 *          periodKey is 'YYYY-MM' for recurring, null for one_time.
 * @gotcha bounded by a 1000-iteration safety stop, and breaks if nextOccurrence
 *         fails to advance, so a misconfigured recurrence can't infinite-loop.
 */
export function getOccurrencesInRange(expense, rangeStart, rangeEnd) {
  const start = parseLocalDate(expense.start_date);
  if (!start) return [];

  if (expense.type === 'one_time') {
    if (start >= rangeStart && start <= rangeEnd) {
      return [{ date: start, periodKey: null, isFuture: start > new Date() }];
    }
    return [];
  }

  const expEnd = expense.end_date ? parseLocalDate(expense.end_date) : null;
  const results = [];
  let cursor = new Date(start);
  let safety = 0;

  while (cursor <= rangeEnd && safety++ < 1000) {
    if (cursor >= rangeStart && (!expEnd || cursor <= expEnd)) {
      results.push({
        date: new Date(cursor),
        periodKey: `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, '0')}`,
        isFuture: cursor > new Date(),
      });
    }
    const next = nextOccurrence(cursor, expense);
    if (!next || +next <= +cursor) break;
    cursor = next;
  }

  return results;
}

/**
 * Coverage state for a paid-vs-owed pair.
 * @returns {'covered'|'overpaid'|'partial'|'unpaid'} 'overpaid' surfaces the
 *          red OVER badge for any legacy data that beat the cap-enforcement
 *          trigger (trg_check_split_expense_cap).
 */
export function expenseCoverageStatus(covered, total) {
  if (!total || total <= 0) return 'covered';
  if (covered > total + 0.005) return 'overpaid';
  if (covered >= total * 0.9999) return 'covered';
  if (covered > 0) return 'partial';
  return 'unpaid';
}

/**
 * The amount in effect on `date`, from a price-history array sorted ascending
 * by effective_date.
 * @gotcha falls back to the FIRST entry when every entry post-dates `date`, so a
 *         backdated start date still resolves to a price instead of null.
 */
export function getEffectiveAmount(priceHistory, date) {
  if (!priceHistory || priceHistory.length === 0) return null;
  let effective = priceHistory[0];
  for (const entry of priceHistory) {
    if (parseLocalDate(entry.effective_date) <= date) effective = entry;
    else break;
  }
  return parseFloat(effective.amount);
}

export const EXPENSE_FREQUENCIES = ['weekly', 'monthly', 'quarterly', 'annual'];
export const DAYS_OF_WEEK = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
