/**
 * components/shared/Icon.js: the hub's only inline-SVG icon set.
 *
 * The home for a glyph instead of an emoji: any functional UI that wants a mark imports one of
 * these or adds a new one here. One geometric language, drawn to a 16-unit grid at 1.5 stroke
 * with miter joins and butt caps. Consistent with LockIcon.js; intentionally NOT a
 * Material/Lucide drop-in.
 *
 * API mirrors LockIcon exactly: <SomeIcon size={14} title="..." style className />, size
 * defaulting to 12.
 *
 * @invariant color is ALWAYS inherited via currentColor; an icon never sets its own. The
 *            caller's context decides, and status colour comes from the row rather than the
 *            glyph. Orange is never an icon default.
 * @see components/shared/LockIcon.js
 */
import React from 'react';

function Svg({ size = 12, style, className, title, children }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      aria-hidden={title ? undefined : true}
      role={title ? 'img' : undefined}
      focusable="false"
      style={{ display: 'inline-block', verticalAlign: '-1px', flexShrink: 0, ...style }}
      className={className}
    >
      {title ? <title>{title}</title> : null}
      {children}
    </svg>
  );
}

// Solid mass helper - selective fill only where a stroke-only
// glyph would not read at 12px (play triangle, bang dot).
const solid = { fill: 'currentColor', stroke: 'none' };

