// Returns the right file-type component for a MIME type.
export function fileTypeIcon(type, props) {
  let C = FileDocIcon;
  if (type) {
    if (type.startsWith('image/')) C = FileImageIcon;
    else if (type.startsWith('video/')) C = FileVideoIcon;
    else if (type.startsWith('audio/')) C = FileAudioIcon;
    else if (type.includes('zip') || type.includes('rar') || type.includes('compress')) C = FileArchiveIcon;
  }
  return <C {...props} />;
}

