/**
 * The glyph for a contact_methods name. Mirrors fileTypeIcon's shape.
 *
 * @param {string} method the contact_methods.name value
 * @param {object} [props] forwarded to the icon (size, title, className)
 * @returns {JSX.Element|null} null for an unknown or empty method, so an
 *          unrecognised label renders nothing rather than a wrong mark
 */
export function contactMethodIcon(method, props) {
  const C = {
    'email':          EmailIcon,
    'text':           TextIcon,
    'whatsapp':       WhatsAppIcon,
    'direct message': DirectMessageIcon,
  }[(method || '').toLowerCase()];
  return C ? <C {...props} /> : null;
}

