/**
 * utils/rowActivation.js - the props that make a clickable row or card operable by keyboard.
 *
 * Ten table rows and five cards were `onClick` on a `<div>` or a `<tr>` with no role, no
 * tabIndex and no key handler, which is the primary interaction on four of the busiest
 * screens. This is the one home for the four attributes that fix it, so the fifteenth site
 * cannot quietly get three of them.
 *
 * @gotcha `role="button"` on a `<tr>` is deliberate and is what axe accepts here. The obvious
 *         alternative, leaving the row a row and adding `aria-expanded`, is a SERIOUS
 *         `aria-conditional-attr` violation: outside a treegrid, a row may not be expanded.
 * @gotcha a row using this must not also hold a nested `onClick` that lacks its own keyboard
 *         route, or the inner control is reachable by mouse only while the row is not.
 * @see components/shared/LedgerPage.js `.gl-row`
 */

/**
 * @param {function} onActivate - what a click, Enter or Space does
 * @param {object} [state]
 * @param {boolean} [state.pressed] - the row is selected (a detail panel shows it)
 * @param {boolean} [state.expanded] - the row expands something in place
 * @returns {object} props to spread onto the row
 */
export function activationProps(onActivate, state = {}) {
  const props = {
    role: 'button',
    tabIndex: 0,
    onClick: onActivate,
    onKeyDown: (ev) => {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      // Space scrolls the page and Enter submits a form. A row does neither.
      ev.preventDefault();
      onActivate(ev);
    },
  };
  // A row that navigates is neither pressed nor expanded, and must claim neither.
  if (state.pressed !== undefined) props['aria-pressed'] = state.pressed;
  if (state.expanded !== undefined) props['aria-expanded'] = state.expanded;
  return props;
}
