/**
 * utils/format.js - safe formatting utilities.
 *
 * All date/number/string formatting goes through here. Every function is
 * total: it never throws on bad input and returns a fallback string instead, so
 * a malformed DB value can never crash a render.
 *
 * @invariant raw IDs and ISO dates never reach the UI directly; route through
 *            these helpers (fmtDate, fmtMoney, fmtMonth, parseCampaignName, ...).
 */
import { format, parseISO, isValid } from 'date-fns';

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

/**
 * Safely format any date string or Date object.
 * Returns '—' for null, undefined, empty string, or invalid dates.
 */
export function fmtDate(d, fmt = 'MMM d, yyyy') {
  if (!d) return '—';
  try {
    // If it's already a Date object
    if (d instanceof Date) {
      return isValid(d) ? format(d, fmt) : '—';
    }
    // String: use parseISO which handles timezone correctly
    const parsed = parseISO(String(d));
    return isValid(parsed) ? format(parsed, fmt) : '—';
  } catch {
    return '—';
  }
}

/**
 * Safely format a date+time with timezone abbreviation (e.g. "Apr 21, 2026, 3:04 PM CDT").
 */
export function fmtDateTime(d) {
  if (!d) return '—';
  try {
    const date = d instanceof Date ? d : parseISO(String(d));
    if (!isValid(date)) return '—';
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return date.toLocaleString('en-US', {
      month: 'short', day: 'numeric', year: 'numeric',
      hour: 'numeric', minute: '2-digit',
      timeZone: tz, timeZoneName: 'short',
    });
  } catch {
    return '—';
  }
}

/**
 * Safely format a yyyy-MM string into a month label (e.g. "April 2026").
 * Validates the string is a proper yyyy-MM before parsing.
 */
export function fmtMonth(ym) {
  if (!ym || !/^\d{4}-\d{2}$/.test(ym)) return ym || '—';
  try {
    const parsed = parseISO(ym + '-01');
    return isValid(parsed) ? format(parsed, 'MMMM yyyy') : ym;
  } catch {
    return ym;
  }
}

/**
 * A stored percentage as a person writes it: `25.00` becomes `25%`, `12.50` becomes `12.5%`.
 *
 * @param {number|string|null} pct
 * @returns {string} empty for a missing or non-finite value, so a caller renders nothing
 *          rather than "%" on its own.
 */
export function fmtPct(pct) {
  const n = typeof pct === 'number' ? pct : parseFloat(pct);
  if (!Number.isFinite(n)) return '';
  return `${String(Number(n.toFixed(2)))}%`;
}

/**
 * Safely format a money value.
 */
export function fmtMoney(n) {
  if (n == null || n === '') return '—';
  const num = Number(n);
  if (isNaN(num)) return '—';
  return `$${num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

/**
 * Round a money value to cents. The one home for that arithmetic.
 *
 * @param {number|string|null|undefined} n
 * @returns {number} n rounded to two decimals, or 0 for anything not a number
 *
 * @gotcha `toFixed` rounds on the BINARY double, not the decimal value, so a half cent goes
 *         whichever way the double happened to land: `(10.01 * 0.5).toFixed(2)` is `5.00`
 *         while `Math.round(5.005 * 100) / 100` is `5.01`. Over payouts from $10 to $3,000 at
 *         ten common percentages the two disagree on about 5.5% of cases, always with
 *         `toFixed` rounding down. Never write either spelling at a call site.
 * @gotcha Neither form is decimal-exact and this one does not pretend to be. It is
 *         predictable, which `toFixed` is not. The exact fix is refusing sub-cent input at the
 *         control.
 * @invariant This NEVER returns NaN. Callers that need a missing amount to stay missing must
 *            test before calling, as `computeSplitAmounts` does for a null payout.
 */
export function round2(n) {
  return Math.round((Number(n) || 0) * 100) / 100;
}

/**
 * Extract valid yyyy-MM month strings from an array of rows with a date field.
 * Filters out malformed dates (like '20265-03-21') before slicing.
 */
export function extractMonths(rows, dateField = 'invoice_date') {
  return [...new Set(
    rows
      .map(r => r[dateField])
      .filter(d => d && /^\d{4}-\d{2}-\d{2}$/.test(d))
      .map(d => d.slice(0, 7))
  )].sort().reverse();
}

/**
 * A Date as yyyy-MM-dd in LOCAL time, from the parts.
 *
 * @gotcha never `toISOString().slice(0, 10)`, which is the UTC date: west of UTC that is
 *         tomorrow from early evening, and east of UTC a local midnight is the day before.
 *         Both directions put a calendar fact on the wrong day.
 * @param {Date} d
 * @returns {string} 'YYYY-MM-DD'
 */
export function localYMD(d) {
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${m}-${day}`;
}

/**
 * Today as yyyy-MM-dd in local time. Caps `<input type="date" max>` and the validation
 * upper bound on any "already happened" field (cash received, cleared, paid), so a typo
 * cannot silently date a JE years away.
 */
export function todayYMD() {
  return localYMD(new Date());
}

/**
 * Validate that a string is a reasonable date value (yyyy-MM-dd).
 * Used before saving to DB.
 */
export function isValidDateString(d) {
  if (!d) return true; // empty/null is allowed (optional fields)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) return false;
  const parsed = parseISO(d);
  return isValid(parsed);
}

/**
 * Validate a numeric value - returns true if empty (optional) or a valid number.
 */
export function isValidNumber(v) {
  if (v === '' || v == null) return true;
  return !isNaN(parseFloat(v)) && isFinite(v);
}

/**
 * Validate an email address format.
 */
export function isValidEmail(email) {
  if (!email) return true; // optional
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
}

/**
 * Validate a URL format.
 */
export function isValidUrl(url) {
  if (!url) return true; // optional
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

export function isValidTikTokMusicUrl(url) {
  if (!url || !url.trim()) return false;
  try {
    const u = new URL(url.trim());
    if (u.protocol !== 'https:') return false;
    const host = u.hostname.toLowerCase();
    // vm.tiktok.com short links (e.g. https://vm.tiktok.com/ZT9NNoR9A/)
    if (host === 'vm.tiktok.com') return u.pathname.length > 1;
    if (host !== 'www.tiktok.com' && host !== 'tiktok.com') return false;
    const path = u.pathname;
    // Canonical music URL
    if (path.startsWith('/music/') && path !== '/music/' && path !== '/music') return true;
    // Short redirect URLs (e.g. https://www.tiktok.com/t/ZT9NNoR9A/)
    if (/^\/t\/[A-Za-z0-9_-]+\/?$/.test(path)) return true;
    return false;
  } catch { return false; }
}

// Extracts the stable numeric music ID from a full TikTok music URL.
// Returns null for short links (vm.tiktok.com, tiktok.com/t/) - those have no ID in the URL.
// "https://www.tiktok.com/music/Stay-Over-7613782304565087009"       → "7613782304565087009"
// "https://www.tiktok.com/music/Stay-over-by-Onlyfriends-7613782304565087009" → "7613782304565087009"
// "https://vm.tiktok.com/ZT9NNoR9A/"                                → null
export function extractTikTokMusicId(url) {
  const m = String(url || '').match(/\/music\/[^/?#]*-(\d{15,20})(?:[/?#]|$)/);
  return m ? m[1] : null;
}

/**
 * Returns true when the invoice is_in_kind boolean is set.
 */
export function isInKind(flag) {
  return flag === true;
}

/**
 * Parse a free-text hashtag string into a normalised array.
 * Strips leading #s, lowercases, deduplicates, filters empties.
 * Input: "#ad #Sponsored brokerecords, NewMusic"
 * Output: ["ad", "sponsored", "brokerecords", "newmusic"]
 */
export function normalizeHashtags(input) {
  if (!input || typeof input !== 'string') return [];
  return [...new Set(
    input
      .split(/[\s,]+/)
      .map(t => t.replace(/^#+/, '').toLowerCase().trim())
      .filter(Boolean)
  )];
}

/**
 * Parse the internal campaign serial (YYYYMMDD-NN-Creator-Agency Name) into
 * human-readable parts. Returns raw name as agency on parse failure.
 *
 * @invariant Its ONE consumer is utils/campaignLabel.js, which owns what a
 *            campaign is called on screen. Call that instead: a campaign's
 *            headline comes from `campaigns.display_name` now, and reaching for
 *            the serial directly reintroduces the label drift campaignLabel
 *            exists to prevent. This stays only to supply the date/month (the
 *            serial's date is the deal-signed date) and as the pre-display_name
 *            fallback.
 */
export function parseCampaignName(name) {
  if (!name) return { agency: '—', creator: '', month: '', date: '' };
  const match = name.match(/^(\d{4})(\d{2})(\d{2})-\d+-(\w+)-(.+)$/);
  if (!match) return { agency: name, creator: '', month: '', date: '' };
  const [, year, mo, day, creator, agency] = match;
  const idx = parseInt(mo, 10) - 1;
  const month = idx >= 0 && idx < 12 ? `${MONTHS[idx]} ${year}` : '';
  const date  = idx >= 0 && idx < 12 ? `${parseInt(day, 10)} ${MONTHS[idx]} ${year}` : '';
  return { agency, creator, month, date };
}

/**
 * Compact a large count: 171912 -> "172K", 1500000 -> "1.50M".
 *
 * THREE SIGNIFICANT FIGURES, and nothing under 10,000 is compacted at all. The rule matters
 * more than the digits it produces: a creator reads her own view count on the agency
 * dashboard, on Missing Sounds, on a chart axis and on an Analytics milestone, and any two of
 * those disagreeing means one of them is telling her something false about her own work.
 *
 * @param {number|null|undefined} n
 * @returns {string} the compacted string, or an em dash for a missing or non-finite value
 *
 * @gotcha the floor is 10,000 and not 1,000 on purpose. "2K" for 1,912 rounds away 88 views
 *         at the scale where a creator can still count them, and the full number fits.
 * @gotcha a value that rounds UP through its own unit is promoted rather than printed:
 *         999,950 is "1.00M", never "1000K". Without the promotion the K tier can print a
 *         four-digit mantissa, which is four significant figures in a three-figure format.
 * @invariant every surface that compacts a count calls THIS. `shared/agency.js` cannot import
 *            from the hub bundle and carries a copy, pinned to this one by
 *            `utils/__tests__/compactNumber.test.js`.
 */
export function fmtCompact(n) {
  if (n == null || !Number.isFinite(Number(n))) return '—';
  const num = Number(n);
  if (Math.abs(num) < 10000) return num.toLocaleString('en-US');
  const UNITS = [[1e3, 'K'], [1e6, 'M'], [1e9, 'B']];
  let tier = 0;
  while (tier < UNITS.length - 1 && Math.abs(num) >= UNITS[tier + 1][0]) tier++;
  for (;;) {
    const [size, suffix] = UNITS[tier];
    const v = num / size;
    const abs = Math.abs(v);
    const decimals = abs >= 100 ? 0 : abs >= 10 ? 1 : 2;
    // Promote before printing, so the mantissa never carries a fourth figure.
    if (Math.abs(Number(v.toFixed(decimals))) >= 1000 && tier < UNITS.length - 1) { tier++; continue; }
    return v.toFixed(decimals) + suffix;
  }
}
