/**
 * utils/campaignLabel.js - the ONE place the app decides what a campaign is called on screen.
 *
 * A campaign has two names doing different jobs:
 *   `campaign_name`  the internal serial `20260311-01-Mys-Broke Records`, quoted by invoices
 *                    and Stripe descriptions, sorts chronologically. Never a human label.
 *   `display_name`   the human label, derived in the database by `campaign_display_name()`:
 *                      "YTK Media x Mys - JVKE - her (feat. ZVC)"  (1 post, sound known)
 *                      "Broke Records x Mys"                       (2+ posts, or no sound)
 *
 * Every surface routes through `campaignLabelParts`, so do NOT inline
 * `display_name || parseCampaignName(...)` at a call site. `rewardLabel` is the same job for
 * the other thing an invoice can point at, and lives here so the two cannot drift apart.
 *
 * @gotcha The display name deliberately carries NO date, so the muted date beside it is
 *         load-bearing rather than decorative: six Broke Records deals with Mys share one label
 *         and only the date tells them apart. Render `date` (or `month`) where there is room.
 * @see schemas/SCHEMA.sql `campaign_display_name()` and `refresh_campaign_display_name()`
 */
import { fmtMonth, parseCampaignName } from './format';

/**
 * Everything a surface needs to title a campaign.
 *
 * @param {?object} campaign - any row carrying `display_name` + `campaign_name`
 *        (the `campaigns` table, `campaign_payout_summary`, or an embed of
 *        either). A bare string is accepted for the legacy path.
 * @returns {{label: string, month: string, date: string}} `label` is the
 *          headline; `month` ("Mar 2026") and `date` ("11 Mar 2026") come off
 *          the serial, whose date is the deal-signed date.
 * @invariant The fallback to the parsed serial matters during the window between
 *            a campaign being inserted and its trigger writing `display_name`,
 *            and on any row whose select forgot the column. It degrades to the
 *            old agency-only label instead of rendering blank.
 */
export function campaignLabelParts(campaign) {
  const row = typeof campaign === 'string' ? { campaign_name: campaign } : (campaign || {});
  const { agency, month, date } = parseCampaignName(row.campaign_name || '');
  const display = String(row.display_name || '').trim();
  return { label: display || agency, month, date };
}

/**
 * The headline alone, for places with room for one line.
 *
 * @param {?object|string} campaign
 * @returns {string}
 */
export function campaignLabel(campaign) {
  return campaignLabelParts(campaign).label;
}

/**
 * What a platform reward is called on screen: the program, and the month it was earned for.
 *
 * The other thing an invoice can point at. A campaign invoice is titled by its agency or its
 * display name; a reward invoice has neither, and without this it reads as a blank row on
 * every screen that lists what a month's cash was made of.
 *
 * @param {?object} entry - a `platform_reward_entries` row with `program(name)` embedded.
 * @returns {string} e.g. "YouTube Partner Program · July 2026", or EMPTY when the program is
 *          not known.
 * @gotcha empty, never an em dash, and that is the whole point of the return contract. Callers
 *         chain this with `||` behind a campaign label, and a placeholder is truthy: a
 *         placeholder here swallowed the fallback and printed "—" for every reward payment on
 *         the payroll month.
 * @gotcha the month is the reward PERIOD, not when the platform paid. The two differ by weeks
 *         and a screen usually carries the payment date already.
 */
export function rewardLabel(entry) {
  const name = String(entry?.program?.name || '').trim();
  if (!name) return '';
  const ym = String(entry.period_month || '').slice(0, 7);
  return ym ? `${name} · ${fmtMonth(ym)}` : name;
}

/**
 * The `Agency x Creator` half of a display name, built from its parts.
 *
 * For the one surface that must name a campaign consistently with everywhere
 * else while being certain it never states a SOUND: the Missing sounds backlog.
 *
 * @param {?string} agencyName
 * @param {?string} creatorName
 * @returns {string} e.g. "Broke Records x Mys", or an em dash when neither part
 *          is known.
 * @security This composes the base rather than trimming a stored `display_name`,
 *           so the sound a post used never enters the caller's payload at all.
 *           `MissingSounds` asks the creator which sound the agency BRIEFED, and
 *           a single-deliverable campaign's display name is titled by the sound
 *           she actually POSTED (9 of the 35 open rows today). Fetching the name
 *           and slicing it client-side would put the answer one console log away
 *           and turn the task into transcription. @see MissingSounds.js
 * @invariant Mirrors the base that `campaign_display_name()` builds in SQL, so
 *            the backlog and the rest of the app agree on what a deal is called.
 *            If that separator ever changes, change it in both.
 */
export function campaignBaseLabel(agencyName, creatorName) {
  const parts = [agencyName, creatorName].map(v => String(v || '').trim()).filter(Boolean);
  return parts.length ? parts.join(' x ') : '—';
}
