/**
 * components/shared/CampaignCompletion.js: finishing a campaign, and the invoice that issues
 * with it.
 *
 * One home for everything both completion doors need: what completing this campaign is about to
 * do to the money (`completionOutcome`), the figures a reader sees before she commits
 * (`CompletionSummary`), the write (`useCompleteCampaign`), the read that decides whether the
 * step is due at all (`loadCompletionCandidate`) and the phone step itself
 * (`CompletionScreen`). The phone step lives here rather than in `MobilePostPage`, which is at
 * its length ceiling, and both surfaces are thin renderers of this file.
 *
 * @invariant the browser NEVER writes `campaigns.status_id` or an invoice to complete a
 *            campaign. The one writer is the `complete_campaign` RPC, which re-derives every
 *            rule below on the server and posts Pattern A in the same transaction. What is in
 *            this file is a preview and a button.
 * @gotcha the preview and the RPC can honestly disagree, because another session may write
 *         between the read that filled the panel and the tap. Everything the reader is told
 *         AFTERWARDS comes from what the RPC returned, never from what this file predicted.
 * @see schemas/SCHEMA.sql, function `complete_campaign`; docs/MONEY.md section 3 Pattern A
 */
import React, { useCallback, useState } from 'react';
import { addDays } from 'date-fns';
import { supabase } from '../../lib/supabase';
import { fmtDate, fmtMoney, isInKind, localYMD } from '../../utils/format';
import { parseLocalDate } from '../../utils/expenses';
import { campaignLabel } from '../../utils/campaignLabel';
import { BILLED_PAYMENT_VALUES } from '../../utils/statusValues';
import { resolveStatusRow } from '../../utils/statusRow';
import { humanizeError, humanizeReadError } from '../../utils/errors';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { CheckIcon } from './Icon';
import SubmitButton from './SubmitButton';
import { useToast } from './Toast';

/**
 * How many posts one deliverable row stands for. At least one, always.
 *
 * @gotcha `campaign_deliverables.quantity` is nullable with no CHECK, and the Posts field is a
 *         number input whose `min={1}` only advises: the write is `parseInt(x) || 1`, which
 *         passes `-5` through unchanged. A negative slot count made `postedSlots >= totalSlots`
 *         true at `0 >= -5`, so the rule below cleared a campaign with nothing posted. The
 *         floor is the same coercion the two write sites already apply.
 */
export function slotsOf(deliverable) {
  return Math.max(1, Number(deliverable?.quantity) || 1);
}

/**
 * Why this campaign may not be marked Completed yet, as a sentence, or null.
 *
 * Every campaign-status writer must call it, or Completed means one thing at one door and
 * another at the next. It is the courtesy half of the rule: `complete_campaign` refuses the
 * same campaign server side, inside the transaction that would have billed it, and this greys
 * the button and names the reason before anyone taps, which a raised exception cannot do.
 *
 * @gotcha counted in SLOTS, not rows: one `campaign_deliverables` row carries a quantity. A
 *         mirror of the slot sum inside `complete_campaign`; the two must agree, or a reader
 *         is offered a button the database then refuses.
 * @param {object[]} deliverables `campaign_deliverables` rows for the campaign
 * @param {?string} postedDelivId the `status_options` id whose value is 'Posted'
 * @see schemas/SCHEMA.sql, function `complete_campaign`
 */
export function completedBlockedReason(deliverables, postedDelivId) {
  const rows = deliverables || [];
  // On the ROW count, not on the slot total: with `slotsOf` flooring at 1 the two agree, and
  // "no deliverables yet" is a statement about rows.
  if (rows.length === 0) return 'Cannot mark as Completed: this campaign has no deliverables yet.';
  const totalSlots = rows.reduce((sum, d) => sum + slotsOf(d), 0);
  const postedSlots = rows
    .filter((d) => d.draft_status_id === postedDelivId)
    .reduce((sum, d) => sum + slotsOf(d), 0);
  if (postedSlots >= totalSlots) return null;
  const remaining = totalSlots - postedSlots;
  return `Cannot mark as Completed: ${remaining} post${remaining !== 1 ? 's' : ''} still not Posted.`;
}

/**
 * Is this save the one that moves a campaign INTO Completed?
 *
 * @param {object[]} options the `campaign` group from status_options
 * @param {?string} was the campaign's current status id
 * @param {?string} now the id the form is about to write
 * @returns {boolean}
 * @gotcha the TRANSITION, never the destination. Editing any other field on an
 *         already-Completed campaign must not re-run the completion, which would refuse with
 *         "already complete" and lose the edit that was actually being saved.
 */
export function completingHere(options, was, now) {
  const completedId = (options || []).find((o) => o.value === 'Completed')?.id;
  return !!completedId && now === completedId && was !== completedId;
}

/**
 * Days an agency has to pay, counted from the day the post went live.
 *
 * Every agency is on terms whose own words are "due within 30 days of us dropping the post
 * link", so the clock starts at the link and not at the tap. A mirror of the `+ 30` inside
 * `complete_campaign`, which is the figure that actually reaches the column; this copy exists
 * only so the reader is quoted the date she is about to commit to.
 * @see schemas/SCHEMA.sql, function `complete_campaign`
 */
export const DUE_DAYS = 30;

/** Everything the completion step needs about a campaign, in one round trip. */
export const COMPLETION_SELECT =
  'id, campaign_name, display_name, campaign_start_date, contracted_rate, '
  + 'invoices(id, invoice_amount, in_kind_value, is_in_kind, invoice_date, due_date, payment_status_id), '
  + 'campaign_deliverables(id, draft_status_id, actual_post_date)';

/**
 * What completing this campaign is about to do, as four cases and their figures.
 *
 * @param {object} args
 * @param {object} args.campaign the campaign row, for its `contracted_rate` fallback
 * @param {?object} args.invoice its `invoices` row, or null when the read found none
 * @param {?string} args.paymentStatus the invoice's `status_options` VALUE, resolved by the
 *        caller because only a caller holds the vocabulary
 * @param {object[]} args.deliverables the campaign's deliverables, for their post dates
 * @returns {{kind: string, amount: ?number, lastPost: ?string, dueDate: ?string}}
 *          `kind` is 'issue' (an invoice is about to be raised), 'in_kind' (booked in full the
 *          day the deal was created, so no money moves), 'billed' (already invoiced, so every
 *          money field is left as the admin set it) or 'none' (no payment record at all, which
 *          the RPC refuses).
 *
 * @invariant a mirror of the branches `complete_campaign` takes once it has completed the
 *            campaign, in the same order. They must agree, or this screen quotes a figure the
 *            database then declines to write.
 */
export function completionOutcome({ campaign, invoice, paymentStatus, deliverables }) {
  if (!invoice) return { kind: 'none', amount: null, lastPost: null, dueDate: null };

  // The COLUMN decides what an in-kind deal is, never the status value. Same rule the database
  // keeps in `mark_in_kind_received`. @see utils/invoiceMath.js
  if (isInKind(invoice.is_in_kind)) {
    return {
      kind: 'in_kind',
      amount: invoice.in_kind_value ?? invoice.invoice_amount ?? campaign?.contracted_rate ?? null,
      lastPost: null,
      dueDate: null,
    };
  }

  if (BILLED_PAYMENT_VALUES.includes(paymentStatus)) {
    return {
      kind: 'billed',
      amount: invoice.invoice_amount ?? null,
      lastPost: invoice.invoice_date || null,
      dueDate: invoice.due_date || null,
    };
  }

  // ISO dates sort lexically, so the last one is the max without parsing anything.
  const dates = (deliverables || []).map((d) => d.actual_post_date).filter(Boolean).sort();
  const lastPost = dates.length ? dates[dates.length - 1] : null;
  const parsed = lastPost ? parseLocalDate(lastPost) : null;
  return {
    kind: 'issue',
    amount: invoice.invoice_amount ?? campaign?.contracted_rate ?? null,
    lastPost,
    dueDate: parsed ? localYMD(addDays(parsed, DUE_DAYS)) : null,
  };
}

/**
 * Read a campaign back and say whether it is finished, for the surface that has just written a
 * deliverable and needs to know if that was the last one.
 *
 * @returns {Promise<{campaign: ?object, error: *}>} `campaign` is the row when every
 *          deliverable is live and null when work is outstanding. A null WITH a null error is
 *          the only proof there is work left.
 *
 * @gotcha the whole campaign is read back rather than counted off the list on screen, which
 *         holds only what was pending and cannot see a sibling another session posted.
 * @gotcha the outstanding test is done in JS and NOT with `.neq(draft_status_id)`: a bare neq
 *         is SQL `<>`, `null <> uuid` is NULL, and PostgREST drops the row, so a deliverable
 *         with no status at all would be invisible and this would offer to close a campaign
 *         with work still on it. @see .claude/rules/hub-data.md
 */
export async function loadCompletionCandidate({ campaignId, postedStatusId }) {
  if (!campaignId || !postedStatusId) return { campaign: null, error: null };
  const { data, error } = await supabase
    .from('campaigns').select(COMPLETION_SELECT).eq('id', campaignId).maybeSingle();
  if (error) return { campaign: null, error };
  const rows = data?.campaign_deliverables || [];
  if (!rows.length || !rows.every((d) => d.draft_status_id === postedStatusId)) {
    return { campaign: null, error: null };
  }
  return { campaign: data, error: null };
}

/**
 * The one writer of a completed campaign.
 *
 * @param {function} onError given an already humanized feedback object
 * @returns {{complete: function(string): Promise<?object>, saving: boolean}} `complete`
 *          resolves to the RPC's own report of what it did, or null when it refused.
 *
 * @gotcha the RPC is all or nothing, so a null here means the campaign is still Active AND the
 *         invoice is untouched. A caller must not tell the reader that anything landed.
 */
export function useCompleteCampaign(onError) {
  const [saving, setSaving] = useState(false);
  const complete = useCallback(async (campaignId) => {
    setSaving(true);
    const { data, error } = await supabase.rpc('complete_campaign', { p_campaign_id: campaignId });
    setSaving(false);
    if (error) { onError(humanizeError(error)); return null; }
    return data;
  }, [onError]);
  return { complete, saving };
}

/**
 * What the reader is told the invoice will say, before she commits to it.
 *
 * Three lines and no container, deliberately: the amount is the only thing on the step worth
 * drawing the eye, and a card around the figures would put a border in competition with it.
 * `--blue` and never `--orange`, because this is a figure somebody AGREED to rather than cash
 * that has moved; the in-kind arm is `--purple`, which is not money at all.
 * @see docs/DESIGN.md section 2
 */
export function CompletionSummary({ outcome }) {
  if (!outcome || outcome.kind === 'none') return null;
  const purple = outcome.kind === 'in_kind';
  const note = purple
    ? 'Paid in product, so there is nothing to bill. This was recorded when the deal was set up.'
    : outcome.kind === 'billed'
      ? `Already invoiced${outcome.lastPost ? ` on ${fmtDate(outcome.lastPost)}` : ''}. Nothing about the money changes.`
      : outcome.dueDate
        ? `Invoiced today, due ${fmtDate(outcome.dueDate)}`
        : 'Invoiced today';
  return (
    <div>
      <div style={{ fontFamily: 'var(--font-display)', fontSize: 40, lineHeight: 1, letterSpacing: 1, color: purple ? 'var(--purple)' : 'var(--blue)' }}>{fmtMoney(outcome.amount)}</div>
      <div style={{ fontSize: 13, color: 'var(--muted)', marginTop: 8, lineHeight: 1.5, maxWidth: '34ch' }}>{note}</div>
    </div>
  );
}

/**
 * What the reader is told once it has landed, built from the RPC's own report.
 *
 * @param {object} report what `complete_campaign` returned
 * @param {object} campaign the campaign, for its label
 * @returns {{title: string, body: ?string}} a Toast payload
 *
 * @gotcha it never claims the agency has been sent anything, because they have not been. The
 *         invoice becomes real and Patrick sends it.
 */
export function completionToast(report, campaign) {
  if (report?.issued) {
    return { title: `Invoice ${report.invoice_number} is ready`, body: 'Patrick has been told. He sends it to the agency.' };
  }
  return { title: `${campaignLabel(campaign)} is complete`, body: null };
}

/**
 * The phone step: she has just marked the last video, and this says what finishing it does.
 *
 * Rendered INSTEAD of the post screen and the list. No back arrow and no close control: the two
 * buttons are the only exits, because a third that dismisses the step without saying which it
 * chose is how a campaign ends up looking finished on a phone and Active in the database.
 *
 * @gotcha it returns a FRAGMENT and deliberately claims no main landmark. That belongs to the
 *         three shells and to nothing else, so `MobilePostPage` wraps this; a shared component
 *         carrying one would put a second landmark on any page that later rendered it. The
 *         scan that holds the rule reads source text, so do not write the tag in a comment
 *         either. @see src/__tests__/landmarksAndHeadings.test.js
 *
 * @param {object} args
 * @param {object} args.campaign as returned by `loadCompletionCandidate`
 * @param {function} args.onDone called with the RPC report once it lands
 * @param {function} args.onSkip leaves the campaign Active and goes back to the list
 */
export default function CompletionScreen({ campaign, onDone, onSkip }) {
  const toast = useToast();
  const { options } = useStatusOptions();
  const { complete, saving } = useCompleteCampaign(toast.error);
  const invoice = campaign?.invoices?.[0] || null;
  const outcome = completionOutcome({
    campaign,
    invoice,
    paymentStatus: resolveStatusRow(options, 'payment', { statusId: invoice?.payment_status_id })?.value,
    deliverables: campaign?.campaign_deliverables,
  });

  async function run() {
    const report = await complete(campaign.id);
    if (!report) return;
    toast.success(completionToast(report, campaign));
    onDone(report);
  }

  return (
    <>
      <div style={{ padding: '20px 20px 16px', borderBottom: '1px solid var(--border)' }}>
        <div style={{ fontFamily: 'var(--font-display)', fontSize: 26, letterSpacing: 1 }}>
          NYS<span style={{ color: 'var(--orange)' }}>T</span>ERYS
        </div>
      </div>

      <div style={{ flex: 1, padding: '32px 20px', display: 'flex', flexDirection: 'column' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'var(--green)', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase' }}>
          <CheckIcon size={14} />
          Posted
        </div>

        {/* The sentence IS the step. It tells her the one thing she cannot get from the list
            she came from: that there is nothing left on this deal. */}
        <h1 style={{ fontSize: 20, fontWeight: 500, lineHeight: 1.35, margin: '14px 0 0', maxWidth: '22ch' }}>
          That was the last one for {campaignLabel(campaign)}.
        </h1>

        <div style={{ marginTop: 36 }}><CompletionSummary outcome={outcome} /></div>

        <div style={{ marginTop: 'auto', paddingTop: 40, display: 'flex', flexDirection: 'column', gap: 10 }}>
          <SubmitButton saving={saving} className="btn btn-primary" style={{ fontSize: 15, fontWeight: 700, padding: '14px 20px' }} onClick={run} disabled={saving}>
            {outcome.kind === 'issue' ? 'Complete & invoice' : 'Mark complete'}
          </SubmitButton>
          <button className="btn btn-ghost" style={{ padding: '12px 20px' }} onClick={onSkip} disabled={saving}>
            Not yet
          </button>
        </div>
      </div>
    </>
  );
}

/** The read failure the phone reports when it cannot tell whether the campaign is finished. */
export function completionCheckError(error) {
  return {
    ...humanizeReadError(error),
    title: 'Posted, but the campaign was not checked',
    body: 'Your video is saved. We could not tell whether that was the last one, so this deal may still need closing.',
  };
}
